  function createNavigation() { const nav=document.querySelector("nav"); if (!nav || $("mvp-tab-clients")) return; const crm=[...nav.querySelectorAll(".tab-button")].find((b)=>b.dataset.tab==="crm"); const clients=document.createElement("button"); clients.id="mvp-tab-clients"; clients.className="tab-button"; clients.dataset.tab="clients"; clients.type="button"; clients.innerHTML='<span class="nav-icon">C</span><span class="nav-label">Clientes</span>'; const proposals=document.createElement("button"); proposals.id="mvp-tab-proposals"; proposals.className="tab-button"; proposals.dataset.tab="proposals"; proposals.type="button"; proposals.innerHTML='<span class="nav-icon">O</span><span class="nav-label">Propostas</span>'; const reports=document.createElement("button"); reports.id="mvp-tab-reports"; reports.className="tab-button"; reports.dataset.tab="reports"; reports.type="button"; reports.innerHTML='<span class="nav-icon">R</span><span class="nav-label">Relatorios</span>'; crm.insertAdjacentElement("afterend",clients); clients.insertAdjacentElement("afterend",proposals); proposals.insertAdjacentElement("afterend",reports); $("tab-crm").insertAdjacentHTML("afterend",'<section id="tab-clients" class="tab-view"></section><section id="tab-proposals" class="tab-view"></section><section id="tab-reports" class="tab-view"></section>'); }
  function renderCommercialHeader() { const contexts={clients:{eyebrow:"Base universal",title:"Clientes",description:"Cadastro central para CRM, propostas e projetos."},proposals:{eyebrow:"Comercial",title:"Propostas",description:"Monte ambientes manualmente e acompanhe cada negociacao."},reports:{eyebrow:"Inteligencia comercial",title:"Relatorios e KPIs",description:"Indicadores do funil, vendas, produtividade e operacao."}}; const context=contexts[state.activeTab]; if(!context)return; $("page-eyebrow").textContent=context.eyebrow; $("page-title").textContent=context.title; $("page-description").textContent=context.description; document.title=`${context.title} | GP Mirari`; }
