  function renderProposals() { const target=$("tab-proposals"); if(!target)return; const selectedStatus=window.proposalStatus||"all"; const source=(state.proposals||[]).filter((p)=>!p.archivedAt&&(selectedStatus==="all"||p.status===selectedStatus)); const groups=[...source.reduce((map,p)=>{const key=p.groupId||p.id;if(!map.has(key))map.set(key,[]);map.get(key).push(p);return map;},new Map()).values()].map((versions)=>versions.sort((a,b)=>(Number(b.version)||1)-(Number(a.version)||1))); const list=groups.map((versions)=>versions[0]); target.innerHTML=`<main class="saas-module"><div class="saas-module-head"><div><p class="saas-eyebrow">Comercial</p><h2>Propostas</h2><p>Ambientes montados manualmente, com markup e reserva tecnica.</p></div><div class="saas-actions"><button class="saas-button" id="proposal-filter">Filtros</button><button class="saas-button primary" id="new-proposal">Nova proposta</button></div></div><div class="saas-filter-row" id="proposal-filters" hidden><select class="saas-select" id="proposal-status"><option value="all">Todos os status</option>${Object.entries(core().statusText).map(([id,name])=>`<option value="${id}" ${id===selectedStatus?"selected":""}>${name}</option>`).join("")}</select><button class="saas-button primary" id="apply-proposal-filter">Aplicar filtros</button></div><div class="saas-table-wrap"><table class="saas-table"><thead><tr><th>Proposta</th><th>Cliente</th><th>Validade</th><th>Valor final</th><th>Status</th><th></th></tr></thead><tbody>${list.map((p)=>{const versions=(state.proposals||[]).filter((item)=>(item.groupId||item.id)===(p.groupId||p.id)&&!item.archivedAt);return `<tr><td><strong>${esc(p.number)}</strong><span class="saas-subline">${esc(p.name||"Sem nome")} | ${versions.length} versao${versions.length===1?"":"es"} | atual v${p.version||1}</span></td><td>${esc(clientName(p.clientId))}</td><td>${esc(p.validUntil||"-")}</td><td>${core().money(p.totalCents)}</td><td><span class="saas-badge">${core().statusText[p.status]}</span></td><td><button class="saas-button" data-proposal="${p.id}">Abrir</button></td></tr>`;}).join("")||'<tr><td colspan="6">Nenhuma proposta encontrada.</td></tr>'}</tbody></table></div></main>`; $("proposal-filter").onclick=()=>$("proposal-filters").hidden=!$("proposal-filters").hidden; $("apply-proposal-filter").onclick=()=>{window.proposalStatus=$("proposal-status").value;renderProposals();}; $("new-proposal").onclick=()=>openProposal(); document.querySelectorAll("[data-proposal]").forEach((b)=>b.onclick=()=>openProposal(b.dataset.proposal)); }
  function formatDate(value) {
    if (!value) return "Nao informada";
    const parts=String(value).split("-");
    return parts.length===3?`${parts[2]}/${parts[1]}/${parts[0]}`:String(value);
  }
