  function injectCRMProposalHistory(){
    const lead=selectedLead?.();
    const target=document.querySelector("#tab-crm .detail-grid");
    if(!lead||!target||$("crm-linked-proposals"))return;
    const related=(state.proposals||[]).filter((proposal)=>proposal.crmOpportunityRef===lead.id&&!proposal.archivedAt);
    target.insertAdjacentHTML("beforeend",`<article class="panel soft-panel" id="crm-linked-proposals"><div class="section-title"><div><p class="eyebrow">Comercial</p><h2>Propostas vinculadas</h2></div><span class="pill">${related.length}</span></div><div class="history-list">${related.map((proposal)=>`<div class="history-item"><div class="row-between"><strong>${esc(proposal.number)} v${proposal.version||1}</strong><span class="saas-badge">${esc(core().statusText[proposal.status]||proposal.status)}</span></div><small>${esc(proposal.name||"Sem nome")} | apresentada em ${core().money(proposal.totalCents)} | validade ${formatDate(proposal.validUntil)}</small><div class="inline-actions"><button class="secondary" type="button" data-open-crm-proposal="${proposal.id}">Abrir proposta</button></div></div>`).join("")||"<small>Nenhuma proposta vinculada a esta oportunidade.</small>"}</div></article>`);
    document.querySelectorAll("[data-open-crm-proposal]").forEach((button)=>button.onclick=()=>openProposal(button.dataset.openCrmProposal));
  }
  function injectCRM(){
    if(state.activeTab!=="crm"||!selectedLead?.())return;
    const actions=$("save-crm-lead")?.parentElement;
    if(actions&&!$("create-proposal")){const b=document.createElement("button");b.id="create-proposal";b.className="secondary";b.textContent="Criar proposta";b.onclick=()=>openProposal(null,selectedLead().id);actions.insertBefore(b,$("mark-crm-won"));}
    injectCRMProposalHistory();
  }
  function injectSpecifierBirthdays(){
    if(state.activeTab!=="calendar"||$("specifier-birthday-panel"))return;
    const target=$("tab-calendar")?.querySelector("section");
    if(!target)return;
    const today=new Date();
    const currentYear=today.getFullYear();
    const upcoming=(state.specifiers||[]).filter((item)=>item.active!==false&&item.birthDate).map((item)=>{
      const [,month,day]=String(item.birthDate).split("-");
      let date=new Date(currentYear,Number(month)-1,Number(day));
      if(date<today)date=new Date(currentYear+1,Number(month)-1,Number(day));
      const days=Math.ceil((date-today)/86400000);
      return {...item,nextBirthday:date.toISOString().slice(0,10),days};
    }).filter((item)=>item.days<=60).sort((a,b)=>a.days-b.days);
    target.insertAdjacentHTML("beforeend",`<article class="panel card" id="specifier-birthday-panel"><div class="panel-header"><div><p class="eyebrow">Relacionamento</p><h3>Aniversarios de especificadores</h3></div><span class="pill">${upcoming.length}</span></div><div class="calendar-list">${upcoming.map((item)=>`<div class="calendar-row"><div><strong>${esc(item.name)}</strong><br><small>${formatDate(item.nextBirthday)} | ${item.days===0?"Hoje":`${item.days} dias`}</small></div><span class="pill">${esc(item.role||"Parceiro")}</span></div>`).join("")||"<small>Nenhum aniversario de especificador nos proximos 60 dias.</small>"}</div></article>`);
  }
  const reportMoney=(value)=>Number(value||0).toLocaleString("pt-BR",{style:"currency",currency:"BRL"});
  function localReportData(filters={}){const all=leads().filter((lead)=>lead.status!=="Perdida");const start=filters.start?new Date(`${filters.start}T00:00:00`):null;const end=filters.end?new Date(`${filters.end}T23:59:59`):null;const rows=all.filter((lead)=>{const date=new Date(lead.firstContactDate||lead.createdAt||Date.now());return(!start||date>=start)&&(!end||date<=end)&&(!filters.owner||lead.ownerId===filters.owner)&&(!filters.channel||String(lead.source||lead.channel||"")===filters.channel);});const amount=(lead)=>Number(lead.value||lead.estimatedValue||lead.closedValue||0);const won=(lead)=>["Ganha","Fechada","Ganho"].includes(lead.status);const stages=state.crm?.stages||[];const funnel=stages.map((stage)=>{const items=rows.filter((lead)=>lead.stageId===stage.id);return{stage:stage.name||"Etapa",count:items.length,value:items.reduce((sum,lead)=>sum+amount(lead),0),probability:Number(stage.probability||0)};});const channels={};rows.forEach((lead)=>{const name=lead.source||lead.channel||"Nao informado";channels[name]=channels[name]||{channel:name,leads:0,value:0};channels[name].leads++;channels[name].value+=amount(lead);});const users=(state.users||[]).filter((user)=>user.active!==false);const designers=users.map((user)=>{const items=rows.filter((lead)=>lead.ownerId===user.id);return{name:user.name,opportunities:items.length,value:items.reduce((sum,lead)=>sum+amount(lead),0),conversion:items.length?Math.round(items.filter(won).length/items.length*100):0};}).filter((item)=>item.opportunities);const today=new Date();const noNextAction=rows.filter((lead)=>!lead.nextActionDate&&!lead.nextTaskDate).length;const overdue=rows.filter((lead)=>{const date=lead.nextActionDate||lead.nextTaskDate;return date&&new Date(`${date}T23:59:59`)<today;}).length;return{summary:{totalLeads:rows.length,pipelineValue:rows.reduce((sum,lead)=>sum+amount(lead),0),weightedPipeline:rows.reduce((sum,lead)=>sum+amount(lead)*(Number(lead.probability||lead.stageProbability||0)/100),0),conversion:rows.length?Math.round(rows.filter(won).length/rows.length*100):0,noNextAction,overdue},funnel,channels:Object.values(channels),designers};}
  async function fetchCloudReports(filters){const api=typeof getCloudClient==="function"?getCloudClient():null;if(!api?.functions?.invoke)return null;try{const result=await api.functions.invoke("gp-v2-reports",{body:{path:"summary",filters}});return result.error?null:result.data;}catch(_){return null;}}
  function reportCard(label,value,detail){return`<article class="saas-report-kpi"><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(detail||"")}</small></article>`;}
  function renderReports(){const target=$("tab-reports");if(!target||state.activeTab!=="reports")return;const filters=window.reportFilters||{};const data=window.reportCloudData||localReportData(filters);target.innerHTML=`<main class="saas-module reports-module"><div class="saas-module-head"><div><p class="saas-eyebrow">Inteligencia comercial</p><h2>Relatorios e KPIs</h2><p>Indicadores do funil, vendas, produtividade e operacao.</p></div><div class="saas-actions"><button class="saas-button" id="reports-filter-toggle">Filtros</button><button class="saas-button" id="reports-refresh">Atualizar</button></div></div><div class="saas-filter-row reports-filter-row" id="reports-filters" ${window.reportFiltersOpen?"":"hidden"}><div class="saas-field"><label>Inicio</label><input class="saas-input" id="report-start" type="date" value="${esc(filters.start||"")}"></div><div class="saas-field"><label>Fim</label><input class="saas-input" id="report-end" type="date" value="${esc(filters.end||"")}"></div><div class="saas-field"><label>Responsavel</label><select class="saas-select" id="report-owner"><option value="">Todos</option>${(state.users||[]).filter((u)=>u.active!==false).map((u)=>`<option value="${esc(u.id)}" ${u.id===filters.owner?"selected":""}>${esc(u.name)}</option>`).join("")}</select></div><div class="saas-field"><label>Canal</label><input class="saas-input" id="report-channel" placeholder="Todos" value="${esc(filters.channel||"")}"></div><button class="saas-button primary reports-apply" id="reports-apply">Aplicar filtros</button></div><div class="saas-report-grid">${reportCard("Leads no periodo",data.summary.totalLeads,"Oportunidades acompanhadas")}${reportCard("Valor do pipeline",reportMoney(data.summary.pipelineValue),"Valor estimado")}${reportCard("Valor ponderado",reportMoney(data.summary.weightedPipeline),"Valor x probabilidade")}${reportCard("Conversao",`${data.summary.conversion}%`,"Oportunidades ganhas")}${reportCard("Sem proxima tarefa",data.summary.noNextAction,"Acompanhar hoje")}${reportCard("Tarefas atrasadas",data.summary.overdue,"Prioridade comercial")}</div><div class="saas-report-columns"><section class="saas-table-wrap"><div class="saas-section-heading"><div><span>01</span><h4>Funil por etapa</h4></div><p>Volume e valor estimado.</p></div><table class="saas-table"><thead><tr><th>Etapa</th><th>Oportunidades</th><th>Valor</th><th>Probabilidade</th></tr></thead><tbody>${data.funnel.map((row)=>`<tr><td><strong>${esc(row.stage)}</strong></td><td>${row.count}</td><td>${reportMoney(row.value)}</td><td>${row.probability||0}%</td></tr>`).join("")||'<tr><td colspan="4">Nenhuma oportunidade no periodo.</td></tr>'}</tbody></table></section><section class="saas-table-wrap"><div class="saas-section-heading"><div><span>02</span><h4>Canais de aquisicao</h4></div><p>Origem do pipeline.</p></div><table class="saas-table"><thead><tr><th>Canal</th><th>Leads</th><th>Valor</th></tr></thead><tbody>${data.channels.map((row)=>`<tr><td>${esc(row.channel)}</td><td>${row.leads}</td><td>${reportMoney(row.value)}</td></tr>`).join("")||'<tr><td colspan="3">Nenhum canal informado.</td></tr>'}</tbody></table></section></div><section class="saas-table-wrap"><div class="saas-section-heading"><div><span>03</span><h4>Performance por responsavel</h4></div><p>Comparativo comercial.</p></div><table class="saas-table"><thead><tr><th>Responsavel</th><th>Oportunidades</th><th>Valor</th><th>Conversao</th></tr></thead><tbody>${data.designers.map((row)=>`<tr><td><strong>${esc(row.name)}</strong></td><td>${row.opportunities}</td><td>${reportMoney(row.value)}</td><td>${row.conversion}%</td></tr>`).join("")||'<tr><td colspan="4">Nenhum responsavel com oportunidades.</td></tr>'}</tbody></table></section><p class="saas-report-source">Fonte: ${window.reportCloudData?"Supabase relacional":"estado local da aplicacao"}. Os dados relacionais serao preenchidos conforme a operacao SaaS for populada.</p></main>`;$('reports-filter-toggle').onclick=()=>{window.reportFiltersOpen=!window.reportFiltersOpen;renderReports();};$('reports-refresh').onclick=()=>{window.reportCloudData=null;renderReports();fetchCloudReports(filters).then((cloud)=>{if(cloud){window.reportCloudData=cloud;renderReports();}});};$('reports-apply').onclick=()=>{window.reportFilters={start:$('report-start').value,end:$('report-end').value,owner:$('report-owner').value,channel:$('report-channel').value.trim()};window.reportFiltersOpen=false;window.reportCloudData=null;renderReports();fetchCloudReports(window.reportFilters).then((cloud)=>{if(cloud){window.reportCloudData=cloud;renderReports();}});};}
  function openContract(lead, proposal){const c=client(lead.clientId);modal("Dados contratuais",`<p class="saas-notice">Complete os dados obrigatorios antes de criar o projeto.</p><div class="saas-form-grid"><div class="saas-field"><label>Nome/Razao social</label><input class="saas-input" id="contract-name" value="${esc(c?.name||lead.client)}"></div><div class="saas-field"><label>CPF/CNPJ</label><input class="saas-input" id="contract-doc" value="${esc(c?.document||"")}"></div><div class="saas-field"><label>Telefone</label><input class="saas-input" id="contract-phone" value="${esc(c?.contact||lead.contact||"")}"></div><div class="saas-field"><label>E-mail</label><input class="saas-input" id="contract-email" value="${esc(c?.email||"")}"></div><div class="saas-field full"><label>Endereco completo</label><input class="saas-input" id="contract-address" value="${esc(c?.address||"")}"></div></div>`,`<button class="saas-button primary" id="confirm-contract">Confirmar venda</button>`); $("confirm-contract").onclick=()=>{const patch={name:$("contract-name").value.trim(),document:$("contract-doc").value.trim(),contact:$("contract-phone").value.trim(),email:$("contract-email").value.trim(),address:$("contract-address").value.trim(),status:"active"};if(Object.values(patch).slice(0,5).some((v)=>!v)){toast("Preencha todos os dados contratuais.");return;}repo.updateClient(c.id,patch,actor());const id=uid("p");state.projects.push(buildProject({id,name:lead.interest||`Projeto ${patch.name}`,client:patch.name,clientId:c.id,type:lead.source||"CRM",priority:lead.priority,managerId:lead.ownerId,start:todayISO,budget:core().money(proposal.totalCents),notes:`Criado pela proposta ${proposal.number}.`},state.stages));const oldStage=lead.stageId;const wonStage=typeof crmClosedWonStage==="function"?crmClosedWonStage():null;const at=new Date().toISOString();lead.status="Ganha";if(wonStage)lead.stageId=wonStage.id;lead.crmDates=lead.crmDates||{};lead.crmDates.closed=lead.crmDates.closed||todayISO;lead.projectId=id;lead.closedValue=core().money(proposal.totalCents);lead.updatedAt=todayISO;lead.events=lead.events||[];lead.history=lead.history||[];if(typeof crmTouchStageAutomation==="function"&&wonStage)crmTouchStageAutomation(lead,oldStage,lead.stageId,at);lead.events.push({at,type:"won",value:lead.closedValue,proposalId:proposal.id,userId:currentUser()?currentUser().id:""});lead.history.push({at,userId:currentUser()?currentUser().id:"",text:`Negocio fechado pela proposta ${proposal.number} com valor de ${lead.closedValue}. Projeto criado automaticamente.`});state.selectedProjectId=id;closeModal();state.activeTab="projects";render();};}
  function start(){if(!core()||typeof state==="undefined"||typeof render!=="function")return setTimeout(start,30);ensureRepository();createNavigation();legacyRender=render;render=function(){ensureRepository();legacyRender();renderCommercialHeader();renderClients();renderProposals();renderReports();const commercialView=$("tab-"+state.activeTab);if(commercialView){document.querySelectorAll(".tab-view").forEach((view)=>view.classList.add("hidden"));commercialView.classList.remove("hidden");}enforceRoleVisibility();injectCommercialAdmin();injectCRM();injectSpecifierBirthdays();};legacyCloseWon=closeCRMAsWon;closeCRMAsWon=function(){const lead=selectedLead();const proposal=(state.proposals||[]).find((p)=>p.crmOpportunityRef===lead?.id&&p.status==="accepted");if(!proposal)return toast("Registre o aceite de uma proposta antes de fechar.");if(lead.projectId)return toast("Esta oportunidade ja possui projeto.");openContract(lead,proposal);};render();}
  window.addEventListener("DOMContentLoaded",start);
